/*! Local ZIP helper compatible with the JSZip API used by Starlink Admin. */
(function(global){
  function u16(value){var b=new Uint8Array(2);new DataView(b.buffer).setUint16(0,value,true);return b}
  function u32(value){var b=new Uint8Array(4);new DataView(b.buffer).setUint32(0,value>>>0,true);return b}
  function text(value){return new TextEncoder().encode(String(value==null?'':value))}
  function concat(parts){var size=parts.reduce(function(total,part){return total+part.length},0);var out=new Uint8Array(size);var offset=0;parts.forEach(function(part){out.set(part,offset);offset+=part.length});return out}
  var crcTable=null;
  function makeCrcTable(){var table=[];for(var n=0;n<256;n++){var c=n;for(var k=0;k<8;k++){c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1)}table[n]=c>>>0}return table}
  function crc32(data){if(!crcTable)crcTable=makeCrcTable();var crc=0xffffffff;for(var i=0;i<data.length;i++){crc=crcTable[(crc^data[i])&0xff]^(crc>>>8)}return (crc^0xffffffff)>>>0}
  function dosTime(date){return (date.getHours()<<11)|(date.getMinutes()<<5)|Math.floor(date.getSeconds()/2)}
  function dosDate(date){var year=Math.max(1980,date.getFullYear());return ((year-1980)<<9)|((date.getMonth()+1)<<5)|date.getDate()}
  function fileRecord(name,data,offset,date){var nameBytes=text(name);var bytes=data instanceof Uint8Array?data:text(data);var crc=crc32(bytes);var time=dosTime(date);var day=dosDate(date);var common=[u16(20),u16(0x0800),u16(0),u16(time),u16(day),u32(crc),u32(bytes.length),u32(bytes.length),u16(nameBytes.length),u16(0)];
    var local=concat([u32(0x04034b50)].concat(common,[nameBytes,bytes]));
    var central=concat([u32(0x02014b50),u16(20)].concat(common,[u16(0),u16(0),u16(0),u32(0),u32(offset),nameBytes]));
    return {local:local,central:central}
  }
  function JSZip(){this._files=[]}
  JSZip.prototype.file=function(name,data){this._files.push({name:name,data:data});return this};
  JSZip.prototype.generateAsync=function(options){options=options||{};var locals=[];var centrals=[];var offset=0;var date=new Date();this._files.forEach(function(item){var record=fileRecord(item.name,item.data,offset,date);locals.push(record.local);centrals.push(record.central);offset+=record.local.length});var centralStart=offset;var centralData=concat(centrals);var end=concat([u32(0x06054b50),u16(0),u16(0),u16(this._files.length),u16(this._files.length),u32(centralData.length),u32(centralStart),u16(0)]);var zip=concat(locals.concat([centralData,end]));var blob=new Blob([zip],{type:'application/zip'});return Promise.resolve(options.type==='uint8array'?zip:blob)};
  global.JSZip=JSZip;
})(window);
